  const DICT = { en, es, ru, de, fr };
  const LANGS = [["en", "English"], ["es", "Español"], ["ru", "Русский"], ["de", "Deutsch"], ["fr", "Français"]];
  const LOCALE = { en: "en-US", es: "es-ES", ru: "ru-RU", de: "de-DE", fr: "fr-FR" };

  let lang = "en";
  function fill(s, vars) { return String(s).replace(/\{(\w+)\}/g, (_, k) => (vars && vars[k] != null ? vars[k] : "")); }
  function t(key, vars) { const v = (DICT[lang] && DICT[lang][key]) ?? en[key] ?? key; return Array.isArray(v) ? v : fill(v, vars); }
  function tp(key, n, vars) {
    const cat = new Intl.PluralRules(LOCALE[lang]).select(n);
    const d = DICT[lang] || en;
    const k = d[`${key}_${cat}`] != null ? `${key}_${cat}` : `${key}_other`;
    return t(k, Object.assign({ n: n.toLocaleString(LOCALE[lang]) }, vars));
  }
  function apply(root = document) {
    root.querySelectorAll("[data-i18n]").forEach((el) => (el.textContent = t(el.dataset.i18n)));
    root.querySelectorAll("[data-i18n-html]").forEach((el) => (el.innerHTML = t(el.dataset.i18nHtml)));
    root.querySelectorAll("[data-i18n-ph]").forEach((el) => (el.placeholder = t(el.dataset.i18nPh)));
    root.querySelectorAll("[data-i18n-aria]").forEach((el) => el.setAttribute("aria-label", t(el.dataset.i18nAria)));
    document.documentElement.lang = lang;
  }
  function detect() {
    const pref = (navigator.languages || [navigator.language || "en"]).map((l) => String(l).slice(0, 2).toLowerCase());
    return pref.find((l) => DICT[l]) || "en";
  }

  window.I18N = {
    LANGS, LOCALE, t, tp, apply, detect,
    get lang() { return lang; },
    set lang(v) { lang = DICT[v] ? v : "en"; },
    locale: () => LOCALE[lang],
    extend(code, more) { if (DICT[code]) Object.assign(DICT[code], more); },
  };
